INSERT INTO `posts` (`title`, `body`, `author_name`, `created_at`, `updated_at`, `deleted_at`) VALUES
('Getting started with Laravel routing', 'Routes define how every request enters your app. Learn to name them, group them and keep the file readable, which is perfect for small projects and growing teams.', 'Ahmed Hassan', '2026-09-01 09:15:00', '2026-09-01 09:15:00', NULL),
('Eloquent soft deletes explained simply', 'Soft deletes stamp a row instead of removing it. Trash, restore and permanently delete records safely, which is perfect for admin dashboards and any app that needs undo.', 'Mona Ali', '2026-09-03 11:40:00', '2026-09-05 08:20:00', NULL),
('Building forms with Blade components', 'Repeating the same inputs in every view gets old quickly. Small Blade components keep forms consistent and fast to write, which is perfect for teams building many pages.', 'Omar Khaled', '2026-09-04 14:05:00', '2026-09-04 14:05:00', NULL),
('Validating requests the clean way', 'Form requests keep controllers thin and rules reusable. Validate a title, a body and an author in one class, which is perfect for clean, readable and testable code.', 'Sara Mahmoud', '2026-09-06 10:30:00', '2026-09-07 09:10:00', NULL),
('Understanding database migrations and seeders', 'Migrations let you version your database like your code. Create tables, roll them back and fill them with seeders, which is perfect for local development and shared teamwork.', 'Youssef Adel', '2026-09-07 16:25:00', '2026-09-07 16:25:00', NULL),
('Organizing controllers in growing apps', 'Large controllers become painful to maintain over time. Split them into resource controllers and single-action classes, which is perfect for keeping routes tidy and your business logic separate.', 'Nour Ibrahim', '2026-09-09 12:00:00', '2026-09-10 13:45:00', NULL),
('Middleware basics for Laravel beginners', 'Middleware sits between the request and your controller. This draft shows how to create and register one, which is perfect for filtering traffic before it reaches your logic.', 'Sara Mahmoud', '2026-09-10 09:50:00', '2026-09-10 09:50:00', '2026-10-08 10:12:00'),
('Eloquent relationships made really simple', 'Relationships can sound scary at first. Eager loading prevents the N+1 query problem, which is perfect for apps that list many posts with their authors and related comments.', 'Ahmed Hassan', '2026-09-12 15:20:00', '2026-09-13 10:05:00', NULL),
('Using factories for test data', 'Factories create believable posts without manual typing. Define the fields once and generate dozens of rows instantly, which is perfect for demos, local development and automated feature tests.', 'Mona Ali', '2026-09-13 08:45:00', '2026-09-13 08:45:00', NULL),
('Pagination in Laravel without headaches', 'Showing every record on one page does not scale. Use paginate to split results and keep links styled, which is perfect for long lists of posts and comments.', 'Omar Khaled', '2026-09-15 13:10:00', '2026-09-16 11:30:00', NULL),
('Simple authentication with Laravel Breeze', 'Breeze provides login, registration and password reset within minutes. Install it and review the generated files, which is perfect for starting a new project with solid user authentication.', 'Youssef Adel', '2026-09-16 10:00:00', '2026-09-16 10:00:00', NULL),
('Query scopes for cleaner models', 'Repeating the same where clauses invites bugs. Local scopes give filters readable names like published or latest, which is perfect for short queries and models easy to read.', 'Nour Ibrahim', '2026-09-18 17:35:00', '2026-09-19 09:00:00', NULL),
('Handling user file uploads safely', 'Uploads are a common source of security problems. Validate type and size and never trust original names, which is perfect for protecting your server and all your users.', 'Ahmed Hassan', '2026-09-19 11:15:00', '2026-09-19 11:15:00', NULL),
('Test post for layout checking', 'This is only a test post used to check the layout. It can be deleted, which is perfect for cleaning up the dashboard before the final public launch.', 'Ahmed Hassan', '2026-09-21 18:00:00', '2026-09-21 18:00:00', '2026-10-01 07:45:00'),
('Caching queries for faster apps', 'Heavy queries running on every request slow everything down. Cache the results and clear them when data changes, which is perfect for busy public pages and speed-focused applications.', 'Mona Ali', '2026-09-22 09:25:00', '2026-09-23 14:50:00', NULL),
('Writing your first feature test', 'Tests give you confidence to refactor without fear. Visit the home page, create a post and assert it appears, which is perfect for catching regressions before users do.', 'Sara Mahmoud', '2026-09-24 12:40:00', '2026-09-24 12:40:00', NULL),
('Blade layouts and reusable sections', 'A good layout saves you from copying headers everywhere. Define sections and yield them, which is perfect for pages that need extra styles, scripts or a different footer.', 'Omar Khaled', '2026-09-25 10:55:00', '2026-09-26 08:15:00', NULL),
('Laravel environment configuration best practices', 'Secrets must stay out of your repository. Use the .env file and config files wisely, which is perfect for separating local machine settings from the live production server.', 'Youssef Adel', '2026-09-27 15:30:00', '2026-09-27 15:30:00', NULL),
('Flash messages and clean redirects', 'Users deserve clear confirmation after saving a post. Redirect to the dashboard and flash a success message, which is perfect for feedback that disappears on the next request.', 'Nour Ibrahim', '2026-09-28 09:05:00', '2026-09-29 12:20:00', NULL),
('Duplicate: Getting started with routing', 'An accidental copy of the routing article. It was moved to the trash, which is perfect for removing it permanently once nobody on the team needs it anymore.', 'Ahmed Hassan', '2026-09-30 16:00:00', '2026-09-30 16:00:00', '2026-10-10 18:30:00'),
('Route model binding in practice', 'Route model binding fetches records straight from the URL. Type-hint the model in your method, which is perfect for removing repetitive find calls and cleaning up controller actions.', 'Mona Ali', '2026-10-01 10:20:00', '2026-10-01 10:20:00', NULL),
('Authorization with Laravel policies explained', 'Authorization rules belong in one predictable place. Policies map actions to models, which is perfect for deciding who can edit, delete or restore every post in the blog.', 'Sara Mahmoud', '2026-10-03 13:35:00', '2026-10-04 09:40:00', NULL),
('Queues for slow background work', 'Slow tasks should never block the user. Queues move emails and image processing to the background, which is perfect for keeping every page fast, stable and highly responsive.', 'Omar Khaled', '2026-10-04 11:10:00', '2026-10-04 11:10:00', NULL),
('API resources for clean JSON', 'API resources transform models into clean JSON responses. Choose which fields to expose, which is perfect for mobile apps and front-end frameworks that consume your public data directly.', 'Youssef Adel', '2026-10-06 14:25:00', '2026-10-07 10:00:00', NULL),
('Events and listeners explained simply', 'Events and listeners decouple actions from their side effects. Fire an event right after saving, which is perfect for sending notifications, writing logs and updating dashboard statistics separately.', 'Nour Ibrahim', '2026-10-07 16:45:00', '2026-10-07 16:45:00', NULL),
('Localization for multilingual Laravel apps', 'Localization lets one app speak many languages. Store every string in translation files, which is perfect for serving both Arabic and English readers from the same shared codebase.', 'Ahmed Hassan', '2026-10-09 09:30:00', '2026-10-10 11:15:00', NULL),
('Writing your custom Artisan commands', 'Custom Artisan commands automate repetitive chores. Write one in just a few minutes, which is perfect for cleaning old trashed posts, sending reports and running scheduled maintenance jobs.', 'Mona Ali', '2026-10-10 12:50:00', '2026-10-10 12:50:00', NULL),
('Simple search for post lists', 'Search makes large collections of posts usable again. Combine a simple where clause with like, which is perfect for filtering posts by title, body or author name quickly.', 'Sara Mahmoud', '2026-10-11 10:05:00', '2026-10-11 10:05:00', NULL),
('Formatting dates easily with Carbon', 'Dates are much easier with Carbon. Format created_at values for humans, which is perfect for showing readable labels such as two days ago on every single post card.', 'Omar Khaled', '2026-10-12 08:30:00', '2026-10-12 08:30:00', NULL),
('Deploying Laravel apps to production', 'Deployment should be boring and repeatable. Run your migrations, cache the config and restart all workers, which is perfect for shipping updates to production without surprises or downtime.', 'Youssef Adel', '2026-10-12 09:40:00', '2026-10-12 09:40:00', NULL);
